        'smart_album_flags_enabled' => 'Показывать значки умных альбомов (Несортированные, Недавние, В этот день, оценки и т. д.) на миниатюрах умных альбомов.',
        'album_flags_enabled' => 'Показывать значки публичного, скрытого, защищённого паролем и чувствительного альбома на миниатюрах обычных (не умных) альбомов.',
        'public_hidden_flag_enabled' => 'Показывать оранжевый значок глаза на альбомах, доступных только по общей ссылке (скрытых из публичной галереи).',
        'public_visible_flag_enabled' => 'Показывать зелёный значок глаза на публично видимых альбомах.',
        'password_flag_enabled' => 'Показывать значок замка на альбомах, защищённых паролем.',
