        'shared_albums_visibility_default' => 'Определяет, как отображаются альбомы, которыми поделились другие пользователи: show (вместе с собственными альбомами), separate (на вкладках), separate_shared_only (на вкладках, только прямой доступ), hide (не показываются).',
        'timeline_albums_root_enabled' => '',
        'title_bucket_mode' => '"date_prefix" извлекает дату из начала названия дочернего элемента (например, "2020-03 Отпуск"); "alphabetical" группирует по первым N символам названия.',
        'title_bucket_prefix_length' => '',
        'use_admin_dashboard' => '',
